namespace Inventory;

/// <summary>
/// Coordinates cycle counting, discrepancy reconciliation, and inventory valuation.
/// </summary>
public sealed class CycleCountService
{
    private readonly InventoryCountProcessor _countProcessor;
    private readonly DiscrepancyTracker _discrepancyTracker;
    private readonly InventoryValuationService _valuationService;

    public CycleCountService()
    {
        var valuations = new Dictionary<string, decimal>(StringComparer.Ordinal);
        _countProcessor = new InventoryCountProcessor(valuations);
        _discrepancyTracker = new DiscrepancyTracker();
        _valuationService = new InventoryValuationService(valuations);
    }

    public string RecordCount(StockItem item, Warehouse warehouse, int counted) =>
        _countProcessor.RecordCount(item, warehouse, counted);

    public int CountVariance(StockItem item) =>
        _countProcessor.CountVariance(item);

    public string Reconcile(StockItem item) =>
        _discrepancyTracker.Reconcile(item);

    public bool FlagDiscrepancy(StockItem item, string reason) =>
        _discrepancyTracker.Flag(item, reason);

    public decimal UpdateValuation(StockItem item, decimal unitCost) =>
        _valuationService.Update(item, unitCost);
}

internal sealed class InventoryCountProcessor
{
    private readonly Dictionary<string, int> _counts = new(StringComparer.Ordinal);
    private readonly Dictionary<string, decimal> _valuations;

    public InventoryCountProcessor(Dictionary<string, decimal> valuations)
    {
        _valuations = valuations;
    }

    public string RecordCount(StockItem item, Warehouse warehouse, int counted)
    {
        if (string.IsNullOrEmpty(item.Sku))
            return "no sku";
        if (counted < 0)
            return "invalid";
        if (string.IsNullOrEmpty(warehouse.Code))
            return "no warehouse";

        _counts[item.Sku] = counted;
        var variance = counted - item.OnHand;
        if (variance == 0)
            return "match";

        _valuations[item.Sku] = variance * (variance > 0 ? 2.0m : 1.0m);
        if (variance > 100 || variance < -100)
            return "large variance";
        if (counted == 0 && item.OnHand > 0)
            return "zeroed";
        return "recorded";
    }

    public int CountVariance(StockItem item)
    {
        if (string.IsNullOrEmpty(item.Sku))
            return 0;
        if (!_counts.TryGetValue(item.Sku, out var counted))
            return 0;

        var variance = counted - item.OnHand;
        if (variance == 0)
            return 0;
        if (variance > 1000)
            return 1000;
        if (variance < -1000)
            return -1000;
        if (variance > 0 && counted > item.OnHand * 2)
            return variance + 1;
        return variance;
    }
}

internal sealed class DiscrepancyTracker
{
    private readonly List<string> _discrepancies = new();

    public string Reconcile(StockItem item)
    {
        if (string.IsNullOrEmpty(item.Sku))
            return "no sku";

        var available = item.OnHand - item.Reserved;
        if (available < 0)
        {
            _discrepancies.Add($"{item.Sku}:oversold");
            return "oversold";
        }
        if (item.Reserved < 0)
        {
            _discrepancies.Add($"{item.Sku}:negative-reserve");
            return "bad reserve";
        }
        if (item.OnHand == 0 && item.Reserved > 0)
        {
            _discrepancies.Add($"{item.Sku}:phantom-reserve");
            return "phantom";
        }

        if (available > 0 && available < 5)
            _discrepancies.Add($"{item.Sku}:low");
        else if (available > 10000)
            _discrepancies.Add($"{item.Sku}:excess");

        if (_discrepancies.Count > 1000)
            return "too many discrepancies";
        return "reconciled";
    }

    public bool Flag(StockItem item, string reason)
    {
        if (string.IsNullOrEmpty(item.Sku))
            return false;
        if (string.IsNullOrEmpty(reason))
            return false;
        if (reason.Length > 200)
            reason = reason.Substring(0, 200);
        if (_discrepancies.Count > 5000)
            return false;

        string tag;
        if (reason.StartsWith("oversold", StringComparison.Ordinal))
            tag = "critical";
        else if (reason.StartsWith("low", StringComparison.Ordinal))
            tag = "warn";
        else if (reason.StartsWith("excess", StringComparison.Ordinal))
            tag = "info";
        else
            tag = "note";

        _discrepancies.Add($"{item.Sku}:{tag}:{reason}");
        if (tag == "critical" && _discrepancies.Count > 0)
            return true;
        return tag != "note";
    }
}

internal sealed class InventoryValuationService
{
    private readonly Dictionary<string, decimal> _valuations;

    public InventoryValuationService(Dictionary<string, decimal> valuations)
    {
        _valuations = valuations;
    }

    public decimal Update(StockItem item, decimal unitCost)
    {
        if (string.IsNullOrEmpty(item.Sku))
            return 0m;
        if (unitCost < 0m)
            return 0m;

        var basisQty = item.OnHand > 0 ? item.OnHand : 0;
        var value = basisQty * unitCost;
        if (value > 1_000_000m)
            value = 1_000_000m;
        else if (value < 0m)
            value = 0m;

        _valuations[item.Sku] = value;
        if (basisQty == 0 || unitCost == 0m)
            return 0m;
        return value;
    }
}
